package com.sobrenaturaldirector.planner.trace;
import java.util.*;import com.sobrenaturaldirector.decision.model.Intent;import com.sobrenaturaldirector.planner.model.*;
public final class PlanningTrace {private final String requestId,sourceDecisionId,blueprint,result;private final Intent intent;private final List<String> requirements,steps,reasons;public PlanningTrace(String requestId,String source,Intent intent,String blueprint,String result,List<String>requirements,List<String>steps,List<String>reasons){this.requestId=requestId;sourceDecisionId=source;this.intent=intent;this.blueprint=blueprint;this.result=result;this.requirements=Collections.unmodifiableList(new ArrayList<String>(requirements));this.steps=Collections.unmodifiableList(new ArrayList<String>(steps));this.reasons=Collections.unmodifiableList(new ArrayList<String>(reasons));}public String getRequestId(){return requestId;}public String getSourceDecisionId(){return sourceDecisionId;}public Intent getIntent(){return intent;}public String getBlueprint(){return blueprint;}public String getResult(){return result;}public List<String>getRequirements(){return requirements;}public List<String>getSteps(){return steps;}public List<String>getReasons(){return reasons;}}
